"""Field-level schema migration functions."""

from typing import Any, Dict


class FieldMigrator:
    @staticmethod
    def migrate_v1_to_v2(data: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(data)
        # Rename username -> user_name and combine first/last into full_name
        if "username" in out:
            out["user_name"] = out.pop("username")
        fn = out.pop("first_name", "")
        ln = out.pop("last_name", "")
        out["full_name"] = f"{fn} {ln}".strip()
        # BUG: Uses `or` defaulting which replaces explicit 0 / False / empty with fallback!
        out["retry_count"] = out.get("retry_count") or 3
        out["is_active"] = out.get("is_active") or True
        return out

    @staticmethod
    def migrate_v2_to_v3(data: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(data)
        # Restructure full_name and wrap into profile
        profile = {
            "name": out.pop("full_name", ""),
            "active": out.pop("is_active", True),
        }
        out["profile"] = profile
        return out

repo_files.registry.py:
"""Version step migration registry."""

from typing import Callable, Dict, List, Tuple
from migrator import FieldMigrator


class MigrationRegistry:
    def __init__(self):
        self._steps: Dict[Tuple[int, int], Callable] = {}
        self._register_default_steps()

    def _register_default_steps(self):
        self.register_step(1, 2, FieldMigrator.migrate_v1_to_v2)
        self.register_step(2, 3, FieldMigrator.migrate_v2_to_v3)

    def register_step(self, from_v: int, to_v: int, fn: Callable) -> None:
        self._steps[(from_v, to_v)] = fn

    def get_path(self, from_v: int, target_v: int) -> List[Callable]:
        # Sequential single-step hop planner
        path = []
        curr = from_v
        while curr < target_v:
            # BUG: Lookups (curr, curr + 1) but terminates early if intermediate step missing
            # and increments curr even on KeyError
            step_fn = self._steps.get((curr, curr + 1))
            if not step_fn:
                raise ValueError(f"No migration path from {curr} to {curr+1}")
            path.append(step_fn)
            curr += 1
        return path

repo_files.pipeline.py:
"""Schema evolution pipeline executing multi-version transformations."""

from models import SchemaRecord
from registry import MigrationRegistry


class SchemaEvolutionPipeline:
    def __init__(self, registry: MigrationRegistry):
        self.registry = registry

    def upgrade(self, record: SchemaRecord, target_version: int) -> SchemaRecord:
        if record.version == target_version:
            return record
        if record.version > target_version:
            raise ValueError("Downgrades not supported")
        fns = self.registry.get_path(record.version, target_version)
        curr_data = dict(record.data)
        for fn in fns:
            curr_data = fn(curr_data)
        return SchemaRecord(version=target_version, data=curr_data)

